<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
use AISkillsHub\Core\Operations\Users;
$ops=new Users($db,$core->migrator(),$accounts,new AISkillsHub\Core\Accounts\Locks($db));
$member=p12_user('member');$pending=p12_user('pending',false);$operator=p12_user('operator');$other=p12_user('other');$skill=p12_skill('moderated');
$raw=fn($id)=>['roles'=>get_userdata($id)->roles,'verified'=>get_user_meta($id,'_aish_email_verified_at',true),'hash'=>get_user_meta($id,'_aish_verified_email_hash',true)];
$identity=$raw($member);
p12_case('users_service_capability_and_public_summary_privacy',function()use($ops,$member,$admin){wp_set_current_user($member);p12_reject(fn()=>$ops->listing(),'Subscriber denied users listing');wp_set_current_user($admin);$d=$ops->detail($member);p12_assert(!isset($d['email'])&&!isset($d['user_email'])&&!isset($d['user_login']),'No raw email/login in operations summary');p12_assert($d['state']==='active'&&$d['verified']&&$d['revision']===0,'Verified current state');});
$review=p12_review($member,$skill,5);wp_set_current_user($member);$community->setFavorite($skill,true,'en_US',p12_key());
wp_set_current_user($member);$submission=$submissions->save(0,['kind'=>'submit','locale'=>'en_US','source_kind'=>'manual','name'=>'Operations submission '.$run,'summary'=>'Synthetic queued contribution','notes'=>'Private synthetic fixture'],0,'submit',p12_key());
p12_case('users_counts_reuse_real_contributions',function()use($ops,$member,$admin){wp_set_current_user($admin);$r=$ops->summaries([$member])[$member];p12_assert($r['favorites']===1&&$r['reviews']===1,'Real community counts');p12_assert($r['submissions']===1,'Controlled native submit-kind Inbox counted');});
$pauseKey=bin2hex(random_bytes(16));
p12_case('pause_audited_idempotent_preserves_identity_and_invalidates_public_stats',function()use($ops,$member,$skill,$admin,$pauseKey,$raw,$identity,$core,$query){wp_set_current_user($admin);$before=$core->get('community_query')->publicSummary($skill,'en_US');p12_assert($before['count']===1&&$before['favorites']===1,'Actual approved and favorite count');$ops->setState($member,'suspend',0,'Synthetic moderation hold','Manual review completed',$pauseKey);$ops->setState($member,'suspend',0,'Synthetic moderation hold','Manual review completed',$pauseKey);$d=$ops->detail($member);p12_assert($d['revision']===1&&count($d['history'])===1&&$d['state']==='suspended','Single audited idempotent transition');p12_assert($raw($member)===$identity,'Role and verified identity intact');foreach(['en_US','zh_CN']as$l){$s=$core->get('community_query')->publicSummary($skill,$l);p12_assert($s['count']===0&&$s['favorites']===0,'Current suspended identity excluded crosslanguage');p12_assert(!in_array($skill,p12_ids($query->list('most-favorited',$l,['q'=>'Operations QA moderated'])['items']),true),'Rank live eligibility excludes suspended contribution');}});
p12_case('paused_identity_denied_community_submission_and_native_write',function()use($member,$skill,$accounts,$community,$submissions){wp_set_current_user($member);p12_reject(fn()=>$accounts->requireOwner(),'Paused community identity denied');p12_reject(fn()=>$community->setFavorite($skill,false,'en_US',p12_key()),'Paused favorite denied');p12_reject(fn()=>$submissions->save(0,['kind'=>'submit','locale'=>'en_US','source_kind'=>'manual'],0,'draft',p12_key()),'Paused submission denied');p12_reject(fn()=>$accounts->saveProfile(['display_name'=>'Forbidden profile change']),'Account profile endpoint blocked');});
p12_case('stale_replay_conflict_and_explicit_resume',function()use($ops,$member,$admin,$pauseKey,$accounts,$raw,$identity,$skill,$core){wp_set_current_user($admin);p12_reject(fn()=>$ops->setState($member,'suspend',0,'Different payload','Changed',$pauseKey),'Reusedkey payload conflict',['users_conflict']);p12_reject(fn()=>$ops->setState($member,'resume',0,'Review completed','',bin2hex(random_bytes(16))),'Stale revision denied',['users_conflict']);$ops->setState($member,'resume',1,'Review completed','',bin2hex(random_bytes(16)));p12_assert($accounts->state($member)==='active'&&$raw($member)===$identity,'Resume restores identity without grant');$s=$core->get('community_query')->publicSummary($skill,'en_US');p12_assert($s['count']===1&&$s['favorites']===1,'Fresh stats restored from retained relations');});
p12_case('protected_admin_staff_self_and_erasure_state',function()use($ops,$member,$admin,$operator,$other){wp_set_current_user($admin);p12_reject(fn()=>$ops->setState($admin,'suspend',0,'Synthetic hold','Review',bin2hex(random_bytes(16))),'Self admin protected',['users_protected']);get_userdata($operator)->add_cap(Users::CAPABILITY);p12_reject(fn()=>$ops->setState($operator,'suspend',0,'Synthetic hold','Review',bin2hex(random_bytes(16))),'Operator protected',['users_protected']);update_user_meta($other,'_aish_account_deletion_pending','1');p12_reject(fn()=>$ops->setState($other,'suspend',0,'Synthetic hold','Review',bin2hex(random_bytes(16))),'Erasure isolation cannot bypass',['users_erasing']);delete_user_meta($other,'_aish_account_deletion_pending');update_user_meta($other,'_aish_account_state','suspended');p12_reject(fn()=>$ops->setState($other,'resume',0,'Attempt resume foreign hold','',bin2hex(random_bytes(16))),'Unowned suspension remains',['users_conflict']);});
p12_case('pending_verification_cannot_bypass_pause',function()use($ops,$pending,$admin,$accounts,$core){wp_set_current_user($admin);$store=$core->get('account_store');$token=bin2hex(random_bytes(32));$store->transaction(fn()=>$store->issueVerification($pending,'verify_email',get_userdata($pending)->user_email,$token));$ops->setState($pending,'suspend',0,'Pending identity hold','Verify after review',bin2hex(random_bytes(16)));wp_set_current_user(0);p12_reject(fn()=>$accounts->verify($token),'Verification blocked during pause');p12_assert($accounts->state($pending)==='suspended','Pause retained');wp_set_current_user($admin);$ops->setState($pending,'resume',1,'Hold resolved','',bin2hex(random_bytes(16)));p12_assert($accounts->state($pending)==='pending_email'&&!$accounts->verified($pending),'Unverified state restored without verification');});
p12_case('native_administrator_email_change_never_lifts_pause',function()use($ops,$admin,$accounts,$raw){$id=p12_user('nativeemail');wp_set_current_user($admin);$ops->setState($id,'suspend',0,'Identity review','Verify replacement address',bin2hex(random_bytes(16)));$r=wp_update_user(['ID'=>$id,'user_email'=>'p12-new-'.bin2hex(random_bytes(6)).'@example.invalid']);p12_assert(!is_wp_error($r),'Authorized native administrator can change address');p12_assert($accounts->state($id)==='suspended'&&!$accounts->verified($id),'Address change retains suspension and revokes old binding');$ops->setState($id,'resume',1,'Review complete','',bin2hex(random_bytes(16)));p12_assert($accounts->state($id)==='pending_email'&&!$accounts->verified($id),'Resume requires replacement verification');});
p12_case('sensitive_audit_notes_rejected',function()use($ops,$member,$admin){wp_set_current_user($admin);p12_reject(fn()=>$ops->setState($member,'suspend',2,'token=synthetic-sensitive-marker','Review',bin2hex(random_bytes(16))),'Sensitive audit note denied',['users_sensitive_note']);});
update_option('aish_phase12_qa_fixture',['member'=>$member,'other'=>$other,'pending'=>$pending,'operator'=>$operator,'skill'=>$skill,'review'=>$review['id'],'submission'=>$submission['id']],false);
p12_report('Real WordPress/MySQL native-user operations, actual private Inbox/community writes and current public projections; no external mail/API');
